func rowsSessionRead(ctx context.Context, db *ent.Client, ps ...predicate.SessionRead) ([]audit.Live, error) {
	q := db.SessionRead.Query().Where(ps...)
	bare.SessionReadSelectInit(q, nil)

	vs, err := q.Order(entSessionRead.ById()).Limit(audit.RowsPage).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]audit.Live, len(vs))
	for i, v := range vs {
		out[i] = audit.Live{Object: pdid.Id(v.Id), Row: v.Proto()}
	}

	return out, nil
}

