// Resources serves the common Batch and Watch API. project is required so custom
// read layers cannot silently disappear from historical reads. ResourceProjector
// handles bare.Scope and declared secrets; compose any additional read rules.
//
// Watch evaluates a filter in the language the binary links, which is CEL when
// something imports github.com/lesomnus/payday/resource/resourcecel: a process,
// never what its sandbox imports too. A binary that links none refuses a filter.
func Resources(s resource.Server, drv dialect.Driver, guard batch.Guard, w *watch.Watch, project resource1.Project) (*resource1.Server, error) {
	b, err := Batch(s, drv, guard)
	if err != nil {
		return nil, err
	}
	return resource1.New(b, w, project,
		&resource.Access{},
		&resource.Account{},
		&resource.Archived{},
		&resource.Audit{},
		&resource.AuthBinding{},
		&resource.Connection{},
		&resource.Holder{},
		&resource.NotificationReceiptRecord{},
		&resource.NotificationRecord{},
		&resource.Operator{},
		&resource.Outbox{},
		&resource.Owed{},
		&resource.Project{},
		&resource.RowSeal{},
		&resource.Session{},
		&resource.SessionRead{},
		&resource.Task{},
		&resource.TaskLink{},
		&resource.Tenant{},
	)
}

